from httpbin.core import app

def test_cors_preflight_options_nonexistent_path_returns_4xx_not_5xx():
    client = app.test_client()
    r = client.options(
        '/nonexistent-path-xyz-r-httpbin-039',
        headers={
            'Origin': 'http://example.com',
            'Access-Control-Request-Method': 'GET'
        }
    )
    assert r.status_code != 500, f'Server error on unknown path: {r.data}'
    assert r.status_code == 404, f'Expected 404 for unknown path, got {r.status_code}'

test_cors_preflight_options_nonexistent_path_returns_4xx_not_5xx()
